def analise_sentimento_lexico(texto: str) -> dict:
    """Análise de sentimento baseada em léxico para português."""

    lexico_positivo = {
        'bom': 1.0, 'ótimo': 1.5, 'excelente': 2.0, 'amar': 1.5,
        'feliz': 1.2, 'adorei': 1.8, 'maravilhoso': 2.0, 'gostei': 1.0,
        'incrível': 1.8, 'perfeito': 2.0, 'recomendo': 1.3, 'lindo': 1.5,
        'obrigado': 0.8, 'parabéns': 1.5, 'sucesso': 1.2
    }

    lexico_negativo = {
        'ruim': -1.0, 'péssimo': -1.5, 'horrível': -2.0, 'odiar': -1.5,
        'triste': -1.2, 'detestei': -1.8, 'terrível': -2.0, 'frustrado': -1.3,
        'decepcionado': -1.5, 'lixo': -2.0, 'nunca': -0.5, 'problema': -0.8,
        'falha': -1.0, 'erro': -0.8, 'pior': -1.5
    }

    # Normalizar texto
    palavras = texto.lower().split()

    score = 0.0
    palavras_encontradas = []

    for palavra in palavras:
        # Remover pontuação básica
        limpa = palavra.strip('.,!?;:')
        if limpa in lexico_positivo:
            score += lexico_positivo[limpa]
            palavras_encontradas.append((limpa, lexico_positivo[limpa]))
        elif limpa in lexico_negativo:
            score += lexico_negativo[limpa]
            palavras_encontradas.append((limpa, lexico_negativo[limpa]))

    # Classificação
    if score > 0.5:
        sentimento = 'positivo'
    elif score < -0.5:
        sentimento = 'negativo'
    else:
        sentimento = 'neutro'

    return {
        'sentimento': sentimento,
        'score': round(score, 2),
        'palavras_detectadas': palavras_encontradas
    }

# Exemplo de uso
resultado = analise_sentimento_lexico('O filme foi incrível, mas o final foi decepcionado.')
print(resultado)
# {'sentimento': 'neutro', 'score': 0.3, 'palavras_detectadas': [('incrível', 1.8), ('decepcionado', -1.5)]}
```

Limitações desta abordagem: não captura negação ('não foi bom'), ironia, intensificadores ('muito bom'), nem contexto. Modelos baseados em Transformers (como BERTimbau) resolvem a maioria desses problemas.
